  function frameSvg(id) {
    if (!id) return '';
    if (id==='vine') {
      let vine='';
      const top=[[18,7],[42,4],[68,8],[96,5],[126,7],[158,4],[190,8],[222,5],[252,8],[282,4]];
      const bottom=[[22,76],[54,79],[86,75],[118,79],[150,76],[182,79],[214,75],[246,79],[278,76]];
      top.forEach(([x,y],i)=>{ vine += `<rect x='${x}' y='${y}' width='30' height='3' fill='${i%2?'#4f873f':'#3f7436'}'/>`; if(i%2===0) vine+=leaf(x+9,y-4,i%4===0); });
      bottom.forEach(([x,y],i)=>{ vine += `<rect x='${x}' y='${y}' width='32' height='3' fill='${i%2?'#4f873f':'#3f7436'}'/>`; if(i%2) vine+=leaf(x+13,y-5,i%3===0); });
