      vine += flower(10,3,1)+flower(294,2,1)+flower(4,67,1)+flower(300,68,1)+flower(78,1,.8)+flower(229,74,.8)+flower(151,2,.75);
      vine += `<rect x='9' y='9' width='302' height='2' fill='#6ca85a'/><rect x='9' y='77' width='302' height='2' fill='#6ca85a'/><rect x='9' y='9' width='2' height='70' fill='#6ca85a'/><rect x='309' y='9' width='2' height='70' fill='#6ca85a'/>`;
      return `<svg class='ptgg-frame-svg vine' viewBox='0 0 320 88' preserveAspectRatio='none' shape-rendering='crispEdges'>${vine}</svg>`;
    }
    if (id==='starrail') {
      let s=`<rect x='7' y='7' width='306' height='3' fill='#505da7'/><rect x='7' y='78' width='306' height='3' fill='#6f5fb8'/><rect x='7' y='7' width='3' height='74' fill='#505da7'/><rect x='310' y='7' width='3' height='74' fill='#6f5fb8'/>`;
      for(let x=18;x<305;x+=24){ s+=`<rect x='${x}' y='4' width='2' height='2' fill='#fff4b5'/><rect x='${x+9}' y='81' width='2' height='2' fill='#9ae8ff'/>`; }
      s+=`<rect x='35' y='12' width='26' height='2' fill='#75d7ee'/><rect x='55' y='10' width='12' height='2' fill='#fff4b5'/><rect x='250' y='73' width='30' height='2' fill='#dc8cef'/><rect x='278' y='70' width='10' height='2' fill='#fff4b5'/>`;
      return `<svg class='ptgg-frame-svg starrail' viewBox='0 0 320 88' preserveAspectRatio='none' shape-rendering='crispEdges'>${s}</svg>`;
    }
    if (id==='honeygarden') {
      let s=`<rect x='8' y='8' width='304' height='3' fill='#c78b2c'/><rect x='8' y='77' width='304' height='3' fill='#d8a43a'/><rect x='8' y='8' width='3' height='72' fill='#c78b2c'/><rect x='309' y='8' width='3' height='72' fill='#d8a43a'/>`;
      for(let x=16;x<306;x+=20){ s+=`<path d='M${x} 3h8l4 4-4 4h-8l-4-4z' fill='none' stroke='#e8b84e' stroke-width='2'/><path d='M${x+8} 77h8l4 4-4 4h-8l-4-4z' fill='none' stroke='#f1c965' stroke-width='2'/>`; }
      s+=flower(5,3,.8)+flower(299,70,.8);
      return `<svg class='ptgg-frame-svg honeygarden' viewBox='0 0 320 88' preserveAspectRatio='none' shape-rendering='crispEdges'>${s}</svg>`;
    }
    if (id==='moonbranch') {
      let s=`<rect x='8' y='8' width='304' height='2' fill='#9cafca'/><rect x='8' y='78' width='304' height='2' fill='#7d88b5'/><rect x='8' y='8' width='2' height='72' fill='#9cafca'/><rect x='310' y='8' width='2' height='72' fill='#7d88b5'/>`;
      for(let x=20;x<300;x+=28){ s+=`<rect x='${x}' y='5' width='10' height='2' fill='#dce8ef'/><rect x='${x+6}' y='2' width='2' height='5' fill='#dce8ef'/><rect x='${x+8}' y='81' width='9' height='2' fill='#b8a8df'/>`; }
      s+=`<path d='M18 17h2v-4h3v-3h5v2h-3v4h-4v4h-3zM291 67h3v-4h4v-4h5v2h-3v4h-4v4h-5z' fill='#d9e5f0'/>`;
      return `<svg class='ptgg-frame-svg moonbranch' viewBox='0 0 320 88' preserveAspectRatio='none' shape-rendering='crispEdges'>${s}</svg>`;
    }
    let s=`<rect x='7' y='7' width='306' height='4' fill='#344056'/><rect x='7' y='77' width='306' height='4' fill='#344056'/><rect x='7' y='7' width='4' height='74' fill='#344056'/><rect x='309' y='7' width='4' height='74' fill='#344056'/>`;
    for(let x=17;x<300;x+=18){ s+=`<rect x='${x}' y='3' width='8' height='3' fill='${x%36?'#6bd6d1':'#ef7ab7'}'/><rect x='${x+6}' y='82' width='8' height='3' fill='${x%36?'#ffd56d':'#7d8cff'}'/>`; }
    s+=`<rect x='14' y='20' width='4' height='16' fill='#8ee6df'/><rect x='8' y='26' width='16' height='4' fill='#8ee6df'/><rect x='298' y='56' width='6' height='6' fill='#ef7ab7'/><rect x='306' y='48' width='6' height='6' fill='#ffd56d'/>`;
    return `<svg class='ptgg-frame-svg arcade' viewBox='0 0 320 88' preserveAspectRatio='none' shape-rendering='crispEdges'>${s}</svg>`;
  }

  function owned(id){ return Math.max(0,Number(state.inventory[id])||0); }
  function grant(reward){
    const duplicate=owned(reward.id)>0;
    state.inventory[reward.id]=owned(reward.id)+1;
    if(duplicate) state.shards += RARITY[reward.rarity].shards;
    return { ...reward, duplicate };
  }
  function weightedRarity(force=''){
    if(force) return force;
    const roll=Math.random()*100; let sum=0;
    for(const id of ['common','rare','epic','legendary','prismatic']){ sum+=RARITY[id].weight; if(roll<sum) return id; }
    return 'common';
  }
  function drawOne(index,total){
    let force='';
    if(state.legendaryPity>=99) force='legendary';
    else if(state.epicPity>=49) force='epic';
    else if(total===10 && index===9 && !state.lastResults.some(v=>['rare','epic','legendary','prismatic'].includes(v.rarity))) force='rare';
    const rarity=weightedRarity(force);
    const pool=REWARD_POOL.filter(v=>v.rarity===rarity);
    const reward=grant(pick(pool.length?pool:REWARD_POOL));
    state.pulls++;
    state.epicPity=['epic','legendary','prismatic'].includes(rarity)?0:state.epicPity+1;
    state.legendaryPity=['legendary','prismatic'].includes(rarity)?0:state.legendaryPity+1;
    return reward;
  }
  function draw(count){
    if(state.drawing) return;
    const cost=count===10?180:20;
    if(state.coins<cost){ state.message='测试币不足，可以点击补充测试币。'; render(); return; }
    state.coins-=cost; state.drawing=true; state.lastResults=[]; render();
    host.setTimeout(()=>{
      for(let i=0;i<count;i++) state.lastResults.push(drawOne(i,count));
      const best=state.lastResults.slice().sort((a,b)=>Object.keys(RARITY).indexOf(b.rarity)-Object.keys(RARITY).indexOf(a.rarity))[0];
      state.message=`本次抽取完成，最高获得：${best.name}${state.lastResults.some(v=>v.duplicate)?'；重复奖励已转化为碎片。':''}`;
      state.drawing=false; render();
    },650);
  }

  function rewardArt(reward){
    if(reward.type==='badge') return pixelsSvg(BADGES[reward.id.split(':')[1]]);
    if(reward.type==='frame') return `<span class='ptgg-mini-frame'>${frameSvg(reward.id.split(':')[1])}</span>`;
    if(reward.type==='title') return `<span class='ptgg-scroll'>称号</span>`;
    return `<span class='ptgg-prism-gem'>${pixelsSvg(BADGES.prism)}</span>`;
  }

  function equipReward(id){
    const reward=REWARD_POOL.find(v=>v.id===id); if(!reward||!owned(id)) return;
    const key=id.split(':')[1];
    if(reward.type==='badge') state.equipped.badge=key;
    if(reward.type==='frame') state.equipped.frame=key;
